    assert_eq!(candidate("aaaabbbbccccdddd", vec!["aabbccdd", "aaabbbcccddd", "aaaabbbbccccdddd", "aabbbbccccdddd", "aaaabbbcccdddd"]), 5);
    assert_eq!(candidate("qqqqqqqqqqqqqqqqq", vec!["q", "qq", "qqq", "qqqq", "qqqqq", "qqqqqq", "qqqqqqqq", "qqqqqqqqqqqqqqqqq"]), 8);
    assert_eq!(candidate("xxxyyyzzz", vec!["xyzz", "xxyyz", "xxyyzz", "xxxyyyzzz", "xxxyyzzz", "xxxxyyzzz", "xxxyyyyzzz"]), 5);
    assert_eq!(candidate("abbbbbccccdddd", vec!["abc", "abcd", "abbc", "abcdd", "abbbbbccccdddd"]), 3);
    assert_eq!(candidate("aaaaaaaaaabbbbbbbbbbcccccccccc", vec!["aabbbccc", "aaaaaaaaabbbbbbbbbbcccccccc", "aaaaaaaaabbbbbbbbcccccccccc", "aaaaaaaaaabbbbbbbbbbcccccc", "aaaaaaaaaabbbbbbbbbbccccccccccc"]), 4);
    assert_eq!(candidate("mississiissippii", vec!["mississippi", "mississiippii", "mississsippii", "mississssippiii", "mississssiiiiippiii"]), 0);
    assert_eq!(candidate("xyzzzzzzzzzxyzzzzzzzzzxyzzzzzzzzz", vec!["xyzyxzy", "xyzzzxyzzzxyzzz", "xyzzzzxyzzzzxyzzzz", "xyzzzzzzzzxyzzzzzzzzxyzzzzzzzz", "xyzzzzzzzzzxyzzzzzzzzxzzzzzzzzzz"]), 3);
}
